// UX guard against accidental repeated email-code sends. This is not a security boundary;
// Supabase Auth rate limits and server-verified Turnstile remain the actual enforcement.
const IE_EMAIL_CODE_COOLDOWN_MS = 30000;
let iePreferenceSaveQueue = Promise.resolve();
const IE_ALLOWED_NOTIFICATION_PREFS = new Set(['release_updates','band_invites','announcements','unread_badge']);
function ieSaveNotificationPreference(el){
  if(!el || !session || !profile || !sb) return;
  const key=String(el.dataset.pref||'');
  if(!IE_ALLOWED_NOTIFICATION_PREFS.has(key)) return;
  const desired=!!el.checked;
  const before={...(profile.notification_preferences||{})};
  const previous=before[key]!==false;
  const userId=session.user.id;
  profile.notification_preferences={...before,[key]:desired};
  iePreferenceSaveQueue=iePreferenceSaveQueue.catch(()=>{}).then(async()=>{
    if(!session || session.user.id!==userId || !profile) return;
    const snapshot={...(profile.notification_preferences||{})};
    const {error}=await sb.from('profiles').update({notification_preferences:snapshot}).eq('id',userId);
    if(error){
      const current={...(profile.notification_preferences||{})};
      if(current[key]===desired){
        profile.notification_preferences={...current,[key]:previous};
        document.querySelectorAll('[data-pref]').forEach(input=>{if(input.dataset.pref===key)input.checked=previous;});
      }
      toast('Could not save notification preferences. Try again.','error');
      throw error;
    }
    toast('Preference saved','success');
  });
}
function ieEmailCodeCooldownRemaining(){
  try { return Math.max(0, Number(sessionStorage.getItem('ie-email-code-cooldown-until')||0)-Date.now()); }
  catch (_) { return 0; }
}
function ieAssertEmailCodeCooldown(){
  const remaining=ieEmailCodeCooldownRemaining();
  if(remaining>0) throw new Error(`For security, wait ${Math.ceil(remaining/1000)} seconds before requesting another email code.`);
}
function ieStartEmailCodeCooldown(){
  try { sessionStorage.setItem('ie-email-code-cooldown-until',String(Date.now()+IE_EMAIL_CODE_COOLDOWN_MS)); } catch (_) {}
}
